const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to await evaluate
  const getInfo = (obj) => new Promise((resolve, reject) => obj.evaluate((v, e) => e ? reject(e) : resolve(v)));

  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-89.588, 40.693]); // Peoria, IL
  const region = center.buffer(35000).bounds(); // ~35 km radius bounding box
  const sepStart = '2022-09-01', sepEnd = '2022-10-01';
  const octStart = '2022-10-01', octEnd = '2022-11-01';

  // Cropland mask (MODIS MCD12Q1 IGBP: 12 = Croplands, 14 = Cropland/Natural Mosaic)
  const lc = ee.Image('MODIS/006/MCD12Q1/2020_01_01').select('LC_Type1');
  const croplandMask = lc.eq(12).or(lc.eq(14)).selfMask();

  // Compute cropland pixel count at 1000 m for reporting
  const croplandPixDict = await getInfo(croplandMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }));
  const croplandPixels = croplandPixDict && Object.values(croplandPixDict)[0] ? Object.values(croplandPixDict)[0] : 0;
  if (!croplandPixels || croplandPixels === 0) {
    console.log('Cropland Pixels (1km): 0');
    console.log('C2');
    return;
  }

  // 2. Data Acquisition & Processing helpers
  function maskS2sr(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    const scaled = img.updateMask(mask).divide(10000);
    return scaled.select(['B2','B3','B4','B8','B11','B12'], ['blue','green','red','nir','swir1','swir2']);
  }
  function maskScaleL89(img) {
    const qa = img.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    const scaled = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
                      .multiply(0.0000275).add(-0.2)
                      .updateMask(mask);
    return scaled.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'], ['blue','green','red','nir','swir1','swir2']);
  }
  async function buildComposite(start, end) {
    // Try Sentinel-2 SR first
    let source = 'S2';
    let col = ee.ImageCollection('COPERNICUS/S2_SR')
                .filterDate(start, end)
                .filterBounds(region);
    let imgCount = await getInfo(col.size());
    if (!imgCount || imgCount === 0) {
      // Fallback to Landsat 8/9
      source = 'L8/9';
      const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(region);
      const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(region);
      col = l8.merge(l9);
      imgCount = await getInfo(col.size());
      if (!imgCount || imgCount === 0) {
        return { empty: true, source, imgCount: 0 };
      }
      col = col.map(maskScaleL89);
    } else {
      col = col.map(maskS2sr);
    }
    const composite = col.median().clip(region);
    const cm = composite.updateMask(croplandMask);
    const validDict = await getInfo(cm.select('red').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }));
    const valid = validDict && validDict.red ? validDict.red : 0;
    if (!valid || valid === 0) {
      // If S2 produced 0 valid, try Landsat as a second attempt
      if (source === 'S2') {
        const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(region);
        const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(region);
        let lcol = l8.merge(l9);
        const lCount = await getInfo(lcol.size());
        if (!lCount || lCount === 0) {
          return { empty: true, source: 'S2', imgCount: 0 };
        }
        lcol = lcol.map(maskScaleL89);
        const lcomp = lcol.median().clip(region);
        const lcm = lcomp.updateMask(croplandMask);
        const lvalidDict = await getInfo(lcm.select('red').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9
        }));
        const lvalid = lvalidDict && lvalidDict.red ? lvalidDict.red : 0;
        if (!lvalid || lvalid === 0) {
          return { noValid: true, source: 'L8/9', imgCount: lCount, valid: 0 };
        }
        // Use Landsat composite
        const ndvi = lcomp.normalizedDifference(['nir','red']).rename('ndvi');
        const ndwi = lcomp.normalizedDifference(['green','nir']).rename('ndwi');
        const bsi = lcomp.expression(
          '((swir1 + red) - (nir + blue)) / ((swir1 + red) + (nir + blue))',
          {swir1: lcomp.select('swir1'), red: lcomp.select('red'), nir: lcomp.select('nir'), blue: lcomp.select('blue')}
        ).rename('bsi');
        const brown = ndvi.lt(0.35).and(bsi.gt(0)).and(ndwi.lt(0.1))
                        .updateMask(lcm.select('red').mask())
                        .selfMask()
                        .rename('brown');
        const brownDict = await getInfo(brown.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9
        }));
        const brownCount = brownDict && brownDict.brown ? brownDict.brown : 0;
        return { empty: false, source: 'L8/9', imgCount: lCount, valid: lvalid, brown: brownCount };
      }
      // Already Landsat: no valid pixels
      return { noValid: true, source, imgCount, valid: 0 };
    }
    // Compute brown stats on chosen composite
    const ndvi = composite.normalizedDifference(['nir','red']).rename('ndvi');
    const ndwi = composite.normalizedDifference(['green','nir']).rename('ndwi');
    const bsi = composite.expression(
      '((swir1 + red) - (nir + blue)) / ((swir1 + red) + (nir + blue))',
      {swir1: composite.select('swir1'), red: composite.select('red'), nir: composite.select('nir'), blue: composite.select('blue')}
    ).rename('bsi');
    const brown = ndvi.lt(0.35).and(bsi.gt(0)).and(ndwi.lt(0.1))
                    .updateMask(cm.select('red').mask())
                    .selfMask()
                    .rename('brown');
    const brownDict = await getInfo(brown.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }));
    const brownCount = brownDict && brownDict.brown ? brownDict.brown : 0;
    return { empty: false, source, imgCount, valid, brown: brownCount };
  }

  try {
    console.log(`Cropland Pixels (1km): ${croplandPixels}`);

    const sep = await buildComposite(sepStart, sepEnd);
    if (sep.empty) {
      console.log('Sep 2022: Images: 0');
      console.log('C1');
      return;
    }
    if (sep.noValid || !sep.valid) {
      console.log(`Sep 2022: Source=${sep.source}, Images=${sep.imgCount}, Valid=0`);
      console.log('C2');
      return;
    }
    const sepFrac = sep.valid > 0 ? (sep.brown / sep.valid) : null;

    const oct = await buildComposite(octStart, octEnd);
    if (oct.empty) {
      console.log('Oct 2022: Images: 0');
      console.log('C1');
      return;
    }
    if (oct.noValid || !oct.valid) {
      console.log(`Oct 2022: Source=${oct.source}, Images=${oct.imgCount}, Valid=0`);
      console.log('C2');
      return;
    }
    const octFrac = oct.valid > 0 ? (oct.brown / oct.valid) : null;

    // Validate results
    if (sepFrac == null || octFrac == null || !isFinite(sepFrac) || !isFinite(octFrac) || sepFrac < 0 || octFrac < 0 || sepFrac > 1.5 || octFrac > 1.5) {
      console.log('Calc check failed.');
      console.log('C3');
      return;
    }

    const sepCoverPct = (sep.valid / croplandPixels) * 100.0;
    const octCoverPct = (oct.valid / croplandPixels) * 100.0;

    console.log(`Sep 2022: Source=${sep.source}, Images=${sep.imgCount}, Valid=${sep.valid} (${sepCoverPct.toFixed(1)}%), Brown=${sep.brown} (${(sepFrac*100).toFixed(1)}%)`);
    console.log(`Oct 2022: Source=${oct.source}, Images=${oct.imgCount}, Valid=${oct.valid} (${octCoverPct.toFixed(1)}%), Brown=${oct.brown} (${(octFrac*100).toFixed(1)}%)`);

    const diff = (octFrac - sepFrac) * 100.0;
    console.log(`Brown% Δ (Oct - Sep): ${diff.toFixed(1)}%`);

    // Final Answer
    const eps = 0.5; // percentage points to avoid tiny noise
    if (diff > eps) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
